// Lifecycle status of a single reservation.
enum ReservationStatus {
    ACTIVE,     // holding stock, not yet confirmed or expired
    CONFIRMED,  // became part of a real order
    EXPIRED     // released back to available stock without being confirmed
}

// A catalog item with a price and a sellable quantity.
class Product {
    private final String productId; // unique id
    private final String name;       // display name
    private final double price;       // price per unit
    private int availableStock;         // units currently sellable, not held by any active reservation

    public Product(String productId, String name, double price, int availableStock) {
        this.productId = productId;     // store id
        this.name = name;                 // store name
        this.price = price;                 // store price
        this.availableStock = availableStock; // store starting stock
    }

    public String getProductId() { return productId; }     // id getter
    public double getPrice() { return price; }               // price getter
    public int getAvailableStock() { return availableStock; }  // stock getter
    public void decreaseStock(int amount) { availableStock -= amount; } // hold stock, called on reservation
    public void increaseStock(int amount) { availableStock += amount; }  // release stock, called on expiry
}

// A time-bounded hold against a product's stock for a specific quantity.
class Reservation {
    private final String reservationId; // unique id, e.g. R1
    private final String productId;      // which product this holds stock for
    private final int quantity;           // how many units are held
    private final int expiresAt;           // the virtual time this hold expires
    private ReservationStatus status;       // current lifecycle state

    public Reservation(String reservationId, String productId, int quantity, int expiresAt) {
        this.reservationId = reservationId; // store id
        this.productId = productId;          // store product
        this.quantity = quantity;             // store quantity
        this.expiresAt = expiresAt;            // store expiry time
        this.status = ReservationStatus.ACTIVE; // starts active
    }

    public String getReservationId() { return reservationId; } // id getter
    public String getProductId() { return productId; }           // product getter
    public int getQuantity() { return quantity; }                  // quantity getter
    public int getExpiresAt() { return expiresAt; }                  // expiry getter
    public ReservationStatus getStatus() { return status; }            // status getter
    public void setStatus(ReservationStatus status) { this.status = status; } // status setter
}

// The finalized result of confirming one or more reservations at checkout.
class Order {
    private final String orderId;   // unique id, e.g. O1
    private final String userId;      // who placed it
    private final double totalAmount;   // final price after discount
    private String status;               // CONFIRMED

    public Order(String orderId, String userId, double totalAmount) {
        this.orderId = orderId;         // store id
        this.userId = userId;             // store buyer
        this.totalAmount = totalAmount;     // store final total
        this.status = "CONFIRMED";           // starts confirmed
    }

    public String getOrderId() { return orderId; }         // id getter
    public double getTotalAmount() { return totalAmount; }    // total getter
}

// Creates sequential, correctly-prefixed ids for reservations and orders.
class ShoppingIdFactory {
    private int reservationCounter = 0; // running id counter for reservations
    private int orderCounter = 0;         // running id counter for orders

    public String nextReservationId() {
        reservationCounter++;                    // bump id counter
        return "R" + reservationCounter;          // e.g. R1
    }

    public String nextOrderId() {
        orderCounter++;                    // bump id counter
        return "O" + orderCounter;          // e.g. O1
    }
}

