// Strategy interface: how a coupon code translates into a discount.
interface DiscountStrategy {
    double discountPercent(String couponCode); // fraction to discount, e.g. 0.10 for 10 percent
}

// A simple flat lookup from coupon code to discount percentage.
class PercentageDiscountStrategy implements DiscountStrategy {
    @Override
    public double discountPercent(String couponCode) {
        if (couponCode == null) return 0.0;               // no coupon supplied, no discount
        if (couponCode.equals("SAVE10")) return 0.10;        // 10 percent off
        return 0.0;                                            // unrecognized code, no discount
    }
}

// Observer interface: reacts to shopping lifecycle events.
interface ShoppingObserver {
    void onReservationCreated(Reservation reservation);           // stock held successfully
    void onReservationRejected(String productId, String reason);    // reservation could not be created
    void onOrderConfirmed(Order order);                              // checkout succeeded
    void onReservationExpired(Reservation reservation);               // a hold was released without being confirmed
}

// Simple observer that prints events to the console.
class ConsoleShoppingObserver implements ShoppingObserver {
    @Override
    public void onReservationCreated(Reservation reservation) {
        System.out.println("Reservation " + reservation.getReservationId() + " created for " + reservation.getProductId() + ", qty " + reservation.getQuantity());
    }

    @Override
    public void onReservationRejected(String productId, String reason) {
        System.out.println("Reservation rejected for " + productId + ": " + reason);
    }

    @Override
    public void onOrderConfirmed(Order order) {
        System.out.println("Order " + order.getOrderId() + " confirmed, total " + order.getTotalAmount());
    }

    @Override
    public void onReservationExpired(Reservation reservation) {
        System.out.println("Reservation " + reservation.getReservationId() + " expired and released");
    }
}

