// Custom exceptions for the realistic failure modes.
class OutOfStockException extends RuntimeException {
    public OutOfStockException(String msg) { super(msg); }
}
class ReservationExpiredException extends RuntimeException {
    public ReservationExpiredException(String msg) { super(msg); }
}
class InvalidReservationException extends RuntimeException {
    public InvalidReservationException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class ShoppingService {
    private final java.util.Map<String, Product> products = new java.util.HashMap<>();           // productId -> Product
    private final java.util.Map<String, Reservation> reservations = new java.util.HashMap<>();     // reservationId -> Reservation
    private final DiscountStrategy discountStrategy; // pluggable discount policy
    private final java.util.List<ShoppingObserver> observers = new java.util.ArrayList<>(); // listeners
    private static final int RESERVATION_WINDOW = 10; // how long a hold lasts, in virtual time units

    public ShoppingService(DiscountStrategy discountStrategy) {
        this.discountStrategy = discountStrategy; // store chosen policy
    }

    public void addProduct(Product product) { products.put(product.getProductId(), product); } // register a product
    public void addObserver(ShoppingObserver observer) { observers.add(observer); }               // register a listener

    // Reserves a quantity of a product if enough stock is available, holding it for a limited window.
    public synchronized Reservation reserveItem(String productId, int quantity, int currentTime, ShoppingIdFactory factory) {
        Product product = products.get(productId);                       // look up product
        if (product.getAvailableStock() < quantity) {                       // not enough stock
            for (ShoppingObserver obs : observers) obs.onReservationRejected(productId, "Out of stock"); // notify
            throw new OutOfStockException("Not enough stock for " + productId);
        }
        product.decreaseStock(quantity);                                     // hold the stock immediately
        String reservationId = factory.nextReservationId();                    // build id
        Reservation reservation = new Reservation(reservationId, productId, quantity, currentTime + RESERVATION_WINDOW); // build reservation
        reservations.put(reservationId, reservation);                           // store it
        for (ShoppingObserver obs : observers) obs.onReservationCreated(reservation); // notify
        return reservation; // hand back to caller
    }

    // Confirms a set of reservations into a finalized order, applying a discount, if none have expired.
    public synchronized Order checkout(String userId, java.util.List<String> reservationIds, String couponCode, int currentTime, ShoppingIdFactory factory) {
        double subtotal = 0.0;                                              // running subtotal across all confirmed reservations
        for (String reservationId : reservationIds) {                         // validate every reservation first
            Reservation reservation = reservations.get(reservationId);          // look up reservation
            if (reservation == null) throw new InvalidReservationException("Unknown reservation: " + reservationId);
            if (currentTime >= reservation.getExpiresAt()) {                      // this reservation has expired
                Product product = products.get(reservation.getProductId());          // its product
                product.increaseStock(reservation.getQuantity());                       // release the held stock
                reservation.setStatus(ReservationStatus.EXPIRED);                          // mark expired
                for (ShoppingObserver obs : observers) obs.onReservationExpired(reservation); // notify
                throw new ReservationExpiredException("Reservation " + reservationId + " has expired");
            }
            Product product = products.get(reservation.getProductId());          // look up its product for pricing
            subtotal += product.getPrice() * reservation.getQuantity();            // add this line's cost
        }
        double discount = discountStrategy.discountPercent(couponCode);       // discount fraction from the coupon
        double total = subtotal * (1.0-discount);                              // final total after discount
        for (String reservationId : reservationIds) {                            // now confirm every reservation
            reservations.get(reservationId).setStatus(ReservationStatus.CONFIRMED); // mark confirmed
        }
        String orderId = factory.nextOrderId();                                  // build order id
        Order order = new Order(orderId, userId, total);                           // build order
        for (ShoppingObserver obs : observers) obs.onOrderConfirmed(order);          // notify
        return order; // hand back to caller
    }

    // Releases any active reservation whose expiry has passed, without anyone attempting checkout.
    public synchronized void expireReservations(int currentTime) {
        for (Reservation reservation : reservations.values()) {                 // scan every reservation
            if (reservation.getStatus() == ReservationStatus.ACTIVE && currentTime >= reservation.getExpiresAt()) {
                Product product = products.get(reservation.getProductId());        // its product
                product.increaseStock(reservation.getQuantity());                     // release the held stock
                reservation.setStatus(ReservationStatus.EXPIRED);                        // mark expired
                for (ShoppingObserver obs : observers) obs.onReservationExpired(reservation); // notify
            }
        }
    }
}

