#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class OutOfStockException : public runtime_error {
public: OutOfStockException(const string& msg) : runtime_error(msg) {}
};
class ReservationExpiredException : public runtime_error {
public: ReservationExpiredException(const string& msg) : runtime_error(msg) {}
};
class InvalidReservationException : public runtime_error {
public: InvalidReservationException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class ShoppingService {
    map<string, Product> products;                    // productId -> Product
    map<string, Reservation> reservations;            // reservationId -> Reservation
    shared_ptr<DiscountStrategy> discountStrategy;   // pluggable discount policy
    vector<shared_ptr<ShoppingObserver>> observers; // listeners
    static const int RESERVATION_WINDOW = 10;          // how long a hold lasts, in virtual time units

public:
    ShoppingService(shared_ptr<DiscountStrategy> strategy) : discountStrategy(strategy) {}

    void addProduct(Product product) { products.insert({product.productId, product}); } // register a product
    void addObserver(shared_ptr<ShoppingObserver> observer) { observers.push_back(observer); } // register a listener

    Reservation reserveItem(string productId, int quantity, int currentTime, ShoppingIdFactory& factory) {
        Product& product = products.at(productId);                       // look up product
        if (product.availableStock < quantity) {                            // not enough stock
            for (auto& obs : observers) obs->onReservationRejected(productId, "Out of stock"); // notify
            throw OutOfStockException("Not enough stock for " + productId);
        }
        product.decreaseStock(quantity);                                     // hold the stock immediately
        string reservationId = factory.nextReservationId();                    // build id
        Reservation reservation(reservationId, productId, quantity, currentTime + RESERVATION_WINDOW); // build reservation
        reservations.insert({reservationId, reservation});                       // store it
        for (auto& obs : observers) obs->onReservationCreated(reservation);         // notify
        return reservation; // hand back to caller
    }

    Order checkout(string userId, vector<string> reservationIds, string couponCode, int currentTime, ShoppingIdFactory& factory) {
        double subtotal = 0.0;                                              // running subtotal across all confirmed reservations
        for (auto& reservationId : reservationIds) {                          // validate every reservation first
            auto it = reservations.find(reservationId);                         // look up reservation
            if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
            Reservation& reservation = it->second;
            if (currentTime >= reservation.expiresAt) {                            // this reservation has expired
                Product& product = products.at(reservation.productId);               // its product
                product.increaseStock(reservation.quantity);                           // release the held stock
                reservation.status = ReservationStatus::EXPIRED;                         // mark expired
                for (auto& obs : observers) obs->onReservationExpired(reservation);        // notify
                throw ReservationExpiredException("Reservation " + reservationId + " has expired");
            }
            Product& product = products.at(reservation.productId);               // look up its product for pricing
            subtotal += product.price * reservation.quantity;                       // add this line's cost
        }
        double discount = discountStrategy->discountPercent(couponCode);       // discount fraction from the coupon
        double total = subtotal * (1.0-discount);                               // final total after discount
        for (auto& reservationId : reservationIds) {                              // now confirm every reservation
            reservations.at(reservationId).status = ReservationStatus::CONFIRMED;  // mark confirmed
        }
        string orderId = factory.nextOrderId();                                   // build order id
        Order order(orderId, userId, total);                                        // build order
        for (auto& obs : observers) obs->onOrderConfirmed(order);                     // notify
        return order; // hand back to caller
    }

    void expireReservations(int currentTime) {
        for (auto& entry : reservations) {                                    // scan every reservation
            Reservation& reservation = entry.second;
            if (reservation.status == ReservationStatus::ACTIVE && currentTime >= reservation.expiresAt) {
                Product& product = products.at(reservation.productId);            // its product
                product.increaseStock(reservation.quantity);                         // release the held stock
                reservation.status = ReservationStatus::EXPIRED;                       // mark expired
                for (auto& obs : observers) obs->onReservationExpired(reservation);       // notify
            }
        }
    }
};

