        double total = subtotal * (1.0-discount);
        for (String reservationId : reservationIds) {
            reservations.get(reservationId).setStatus(ReservationStatus.CONFIRMED);
        }
        String orderId = factory.nextOrderId();
        Order order = new Order(orderId, userId, total);
        for (ShoppingObserver obs : observers) obs.onOrderConfirmed(order);
        return order;
    }

    public synchronized void expireReservations(int currentTime) {
        for (Reservation reservation : reservations.values()) {
            if (reservation.getStatus() == ReservationStatus.ACTIVE && currentTime >= reservation.getExpiresAt()) {
                Product product = products.get(reservation.getProductId());
                product.increaseStock(reservation.getQuantity());
                reservation.setStatus(ReservationStatus.EXPIRED);
                for (ShoppingObserver obs : observers) obs.onReservationExpired(reservation);
            }
        }
    }
