using namespace std;

enum class ReservationStatus { ACTIVE, CONFIRMED, EXPIRED };

class Product {
public:
    string productId;
    string name;
    double price;
    int availableStock;

    Product() {}
    Product(string id, string n, double p, int stock) : productId(id), name(n), price(p), availableStock(stock) {}

    void decreaseStock(int amount) { availableStock -= amount; }
    void increaseStock(int amount) { availableStock += amount; }
};

class Reservation {
public:
    string reservationId;
    string productId;
    int quantity;
    int expiresAt;
    ReservationStatus status;

    Reservation() {}
    Reservation(string id, string pId, int qty, int expiry)
        : reservationId(id), productId(pId), quantity(qty), expiresAt(expiry), status(ReservationStatus::ACTIVE) {}
};

class Order {
public:
    string orderId;
    string userId;
    double totalAmount;
    string status;

    Order() : totalAmount(0.0) {}
    Order(string id, string user, double total) : orderId(id), userId(user), totalAmount(total), status("CONFIRMED") {}
};

class ShoppingIdFactory {
    int reservationCounter = 0;
    int orderCounter = 0;

public:
    string nextReservationId() {
        reservationCounter++;
        return "R" + to_string(reservationCounter);
    }

    string nextOrderId() {
        orderCounter++;
        return "O" + to_string(orderCounter);
    }
};

class DiscountStrategy {
public:
    virtual double discountPercent(string couponCode) = 0;
    virtual ~DiscountStrategy() {}
};

class PercentageDiscountStrategy : public DiscountStrategy {
public:
    double discountPercent(string couponCode) override {
        if (couponCode.empty()) return 0.0;
        if (couponCode == "SAVE10") return 0.10;
        return 0.0;
    }
};

class ShoppingObserver {
public:
    virtual void onReservationCreated(const Reservation& reservation) = 0;
    virtual void onReservationRejected(const string& productId, const string& reason) = 0;
    virtual void onOrderConfirmed(const Order& order) = 0;
    virtual void onReservationExpired(const Reservation& reservation) = 0;
    virtual ~ShoppingObserver() {}
};

class ConsoleShoppingObserver : public ShoppingObserver {
public:
    void onReservationCreated(const Reservation& reservation) override {
        cout << "Reservation " << reservation.reservationId << " created for " << reservation.productId << ", qty " << reservation.quantity << endl;
    }
    void onReservationRejected(const string& productId, const string& reason) override {
        cout << "Reservation rejected for " << productId << ": " << reason << endl;
    }
    void onOrderConfirmed(const Order& order) override {
        cout << "Order " << order.orderId << " confirmed, total " << order.totalAmount << endl;
    }
    void onReservationExpired(const Reservation& reservation) override {
        cout << "Reservation " << reservation.reservationId << " expired and released" << endl;
    }
};

class OutOfStockException : public runtime_error {
public: OutOfStockException(const string& msg) : runtime_error(msg) {}
};
class ReservationExpiredException : public runtime_error {
public: ReservationExpiredException(const string& msg) : runtime_error(msg) {}
};
class InvalidReservationException : public runtime_error {
public: InvalidReservationException(const string& msg) : runtime_error(msg) {}
};

class ShoppingService {
    map<string, Product> products;
    map<string, Reservation> reservations;
    shared_ptr<DiscountStrategy> discountStrategy;
    vector<shared_ptr<ShoppingObserver>> observers;
    static const int RESERVATION_WINDOW = 10;

public:
    ShoppingService(shared_ptr<DiscountStrategy> strategy) : discountStrategy(strategy) {}

    void addProduct(Product product) { products.insert({product.productId, product}); }
    void addObserver(shared_ptr<ShoppingObserver> observer) { observers.push_back(observer); }

    Reservation reserveItem(string productId, int quantity, int currentTime, ShoppingIdFactory& factory) {
        Product& product = products.at(productId);
        if (product.availableStock < quantity) {
            for (auto& obs : observers) obs->onReservationRejected(productId, "Out of stock");
            throw OutOfStockException("Not enough stock for " + productId);
        }
        product.decreaseStock(quantity);
        string reservationId = factory.nextReservationId();
        Reservation reservation(reservationId, productId, quantity, currentTime + RESERVATION_WINDOW);
        reservations.insert({reservationId, reservation});
        for (auto& obs : observers) obs->onReservationCreated(reservation);
        return reservation;
    }

    Order checkout(string userId, vector<string> reservationIds, string couponCode, int currentTime, ShoppingIdFactory& factory) {
        double subtotal = 0.0;
        for (auto& reservationId : reservationIds) {
            auto it = reservations.find(reservationId);
            if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
            Reservation& reservation = it->second;
            if (currentTime >= reservation.expiresAt) {
                Product& product = products.at(reservation.productId);
                product.increaseStock(reservation.quantity);
                reservation.status = ReservationStatus::EXPIRED;
                for (auto& obs : observers) obs->onReservationExpired(reservation);
                throw ReservationExpiredException("Reservation " + reservationId + " has expired");
            }
            Product& product = products.at(reservation.productId);
            subtotal += product.price * reservation.quantity;
        }
        double discount = discountStrategy->discountPercent(couponCode);
        double total = subtotal * (1.0-discount);
        for (auto& reservationId : reservationIds) {
            reservations.at(reservationId).status = ReservationStatus::CONFIRMED;
        }
        string orderId = factory.nextOrderId();
        Order order(orderId, userId, total);
        for (auto& obs : observers) obs->onOrderConfirmed(order);
        return order;
    }

    void expireReservations(int currentTime) {
        for (auto& entry : reservations) {
            Reservation& reservation = entry.second;
            if (reservation.status == ReservationStatus::ACTIVE && currentTime >= reservation.expiresAt) {
                Product& product = products.at(reservation.productId);
                product.increaseStock(reservation.quantity);
                reservation.status = ReservationStatus::EXPIRED;
                for (auto& obs : observers) obs->onReservationExpired(reservation);
            }
        }
    }
};

